'use strict';
const phaseOf=d=>d.id===1?'出发 · 芬兰':d.id<=9?'挪威 · 北境海岸':d.id<=15?'冰岛 · 环南岸':d.id===16?'丹麦 · 哥本哈根':'返程 · 赫尔辛基与北京';
const representative=d=>selectedSpots(d).find(k=>pImage(k))||({1:'station',2:'tromso',8:'ballstad',9:'oslo',17:'station'})[d.id]||'';
const highlights=d=>selectedSpots(d).map(k=>DATA.places[k]?.name).filter(Boolean).slice(0,4);
function dateControl(label='选择日期'){return `<button class="date-control" data-dates>${ico('calendar')}<span>${label}</span><span>⌄</span></button>`;}
function dayPagination(d){return `<nav class="day-pagination" aria-label="切换行程日期"><button data-day="${d.id-1}" ${d.id===1?'disabled':''}>← 前一天</button><button data-view="itinerary">全部行程</button><button data-day="${d.id+1}" ${d.id===18?'disabled':''}>后一天 →</button></nav>`;}
function dateRows(){let previous='';const today=tripToday(new Date(),DATA.days,tripCalendarChanges);return DATA.days.map(d=>{const phase=phaseOf(d),header=phase!==previous?`<h2 class="sheet-group">${phase}</h2>`:'';previous=phase;return header+`<button class="date-option ${d.id===state.day?'selected':''}" data-day="${d.id}" ${d.id===state.day?'aria-current="date"':''}><span><strong>${dateText(d.date)}</strong><small>${esc(d.title)} · ${esc(d.region)}</small></span><span>${today.inTrip&&today.day===d.id?'今天':d.id===state.day?'查看中':'↗'}</span></button>`;}).join('');}
let browseCountry='all';
function compactDays(filter='',region=browseCountry){let phase='';const t=tripToday(new Date(),DATA.days,tripCalendarChanges),q=filter.toLocaleLowerCase();return DATA.days.filter(d=>(region==='all'||(region==='transfer'?!['挪威','冰岛'].includes(d.region):d.region===region))&&(!q||[d.title,d.region,d.date,highlights(d).join(' '),...(d.flights||[]).flat()].join(' ').toLocaleLowerCase().includes(q))).map(d=>{const group=phaseOf(d),head=group!==phase?`<h3 class="phase-title">${group}</h3>`:'';phase=group;const key=representative(d),src=smallPhoto(key);return head+`<article class="compact-day"><button class="compact-day-main" data-day="${d.id}"><span class="compact-date"><strong>${shortDate(d.date)}</strong><small>${new Intl.DateTimeFormat('zh-CN',{weekday:'short',timeZone:'UTC'}).format(new Date(d.date+'T12:00:00Z'))}</small>${t.inTrip&&t.day===d.id?'<em>今天</em>':''}</span><span class="compact-copy"><strong>${esc(d.title)}</strong><small>${esc(highlights(d).join(' · ')||(d.flights||[]).map(f=>f[0]+' '+f[1]+'→'+f[4]).join(' · ')||d.region)}</small><span>${d.flights?.length?'航班 · ':''}${d.hotel?'住宿 · ':''}${DATA.bookings.some(b=>b.day===d.id)?'已订活动 · ':''}第${d.id}天${d.id===state.day?' · 查看中':''}</span></span>${src?`<img src="${src}" width="96" height="96" alt="${esc(DATA.places[key]?.name)}" loading="lazy" decoding="async">`:'<span class="compact-air">'+ico('plane')+'</span>'}</button></article>`;}).join('')||'<p class="empty-state">没有匹配的日期或目的地。试试“冰河湖”或“10-30”。</p>';}
function itineraryView(){return `<header class="utility-header"><p class="editor-label">18 DAYS · 18 OCT — 04 NOV</p><h1>全部行程</h1><p>按日期查找，沿真实旅程顺序阅读。</p><div class="utility-actions">${dateControl()}<button data-mapday="all">全程地图 ↗</button></div><div class="segments country-segments" role="group" aria-label="筛选国家">${[['all','全部'],['挪威','挪威'],['冰岛','冰岛'],['transfer','途经城市']].map(([k,n])=>`<button data-country-filter="${k}" aria-pressed="${browseCountry===k}">${n}</button>`).join('')}</div><label class="destination-search">${ico('pin')}<input id="destinationSearch" type="search" placeholder="搜索目的地、日期或航班" aria-label="搜索行程"></label></header><div id="compactIndex">${compactDays()}</div>`;}
function home(){return `<section class="journal-hero"><img src="${pImage('hamnoy')}" width="1176" height="805" alt="Hamnøy红屋与罗弗敦山海" fetchpriority="high" decoding="async"><div class="hero-copy"><p>2026.10.18 — 11.04 · 18天</p><h1>Nordic<br>Journal <em>2026</em></h1><p>挪威 · 冰岛<br>经赫尔辛基与哥本哈根</p><div class="hero-actions"><button class="hero-entry" data-view="itinerary">进入行程 →</button><button class="hero-entry" data-mapday="all">查看旅行路线 ↗</button></div></div><span class="hero-caption">Hamnøy · Lofoten, Norway</span></section><section class="home-index"><div class="home-heading"><div><p class="editor-label">路线与日程</p><h2>十八天的路书</h2></div>${dateControl()}</div><p class="route-sentence">北京 → 赫尔辛基 → 特罗姆瑟 → 罗弗敦 → 博德 → 奥斯陆 → 冰岛 → 哥本哈根 → 赫尔辛基 → 北京</p><div class="home-links"><button data-view="today">打开今日路书 →</button><button data-view="itinerary">查看全部18天 →</button></div><div>${compactDays('','all')}</div></section><footer class="journal-footer"><span>Nordic Journal 2026</span><div><button data-credits>照片来源与许可</button><button data-share>分享路书</button><button data-top>回到顶部 ↑</button><a href="essentials.html">精简资料页 ↗</a></div></footer>`;}
function bookingQuick(b){const day=DATA.days[b.day-1];return `<article class="quick-booking"><div><p class="editor-label">已订活动 · ${shortDate(day.date)}</p><h3>${esc(b.name)}</h3><p><strong>${esc(b.time)}</strong> · ${b.people}位</p><p class="report-target">路书报到目标 <strong>${esc(b.report)}</strong></p><p>${esc(b.place)}</p></div><div class="inline-actions"><button data-booking="${b.day}">预订详情</button>${ext(navLink(DATA.places[b.meeting||b.spot]),'集合点导航','primary-link')}</div></article>`;}
function hotelQuick(d){const h=DATA.hotels[d.hotel];if(!h)return '';return `<article class="quick-hotel"><div><p class="editor-label">今晚住宿 · ${shortDate(d.date)}</p><h3>${esc(h.cn)}</h3><p class="hotel-address">${esc(h.address)}</p></div><div class="inline-actions">${ext(hotelLink(d.hotel),'酒店导航','primary-link')}<button data-hotel="${d.hotel}">住宿详情</button><button data-copy="${esc(h.name+'\n'+h.address)}">复制地址</button></div></article>`;}
function quickInfo(d){return `${d.flights?.length?section('当天航班','FLIGHTS',`<p class="info-caption">起降时间均按当地时区；航班动态须向机场或航司查询。</p><div class="flights">${d.flights.map(flight).join('')}</div>`):''}${DATA.bookings.filter(b=>b.day===d.id).map(bookingQuick).join('')}${hotelQuick(d)}`;}
function routeChoice(d){return d.variants?`<div class="route-choice"><p class="info-caption">路线暂选 · 可随天气与抵达情况调整</p><div class="choice" role="group" aria-label="路线选择">${Object.entries(d.variants).map(([k,v])=>`<button data-variant="${k}" aria-pressed="${(state.variants[d.id]||'A')===k}"><b>${k}</b><span>${esc(v.label)}</span></button>`).join('')}</div><div id="transportOptions">${d.id===1&&state.variants[1]==='B'?transportBox():''}</div></div>`:'';}
function timeCard(d,now=new Date()){const rows=selectedPlan(d),pos=planPosition(d,now,rows);if(!pos.live){const first=rows.find(r=>stepWindow(d,r));return `<p class="info-caption">${d.date}的计划预览 · 未确认实际执行状态。</p>${first?`<div class="preview-first"><span>首项有时间的安排</span><strong>${esc(first.time)} · ${esc(first.stepTitle)}</strong></div>`:''}`;}const summary=(index,label)=>{const r=rows[index];return r?`<div class="plan-summary ${label==='当前计划'?'current-plan':''}"><p class="editor-label">${label} · 按计划时间</p><h3>${esc(r.stepTitle||r.text)}</h3><p><strong>${esc(r.time)}</strong></p>${r.critical?`<p class="critical-note">${esc(r.critical)}</p>`:''}${DATA.bookings.some(b=>b.day===d.id)&&/观鲸|冰洞|浮潜|快艇/.test(r.stepTitle||'')?`<button class="small-link" data-booking="${d.id}">查看活动预订 →</button>`:''}${r.nav?.length?`<p>${r.nav.map(k=>navPoint(k)?.name).filter(Boolean).map(esc).join(' · ')}</p><div class="inline-actions">${r.nav.map(k=>navPoint(k)).filter(Boolean).slice(0,2).map(p=>ext(p.url,p.name+'导航','small-link')).join('')}</div>`:''}<button class="small-link" data-step-focus="${index}">跳到此项安排 ↓</button></div>`:'';};return `${summary(pos.current,'当前计划')}${summary(pos.next,'下一项计划')}${pos.current===-1&&pos.next===-1?'<p class="info-caption">精确时间段已结束，后续仍以路书中的“晚间”或“活动结束后”安排为准。</p>':''}<p class="plan-disclaimer">仅按计划时间提示，不代表活动已开始或完成；大致时段不会被改写成精确时间。</p>`;}
function renderTimeline(d){const rows=selectedPlan(d),pos=planPosition(d);return `<div class="timeline">${rows.map((r,i)=>{const relevant=DATA.bookings.find(b=>b.day===d.id&&(r.nav||[]).includes(b.spot));return `<article id="step-${i}" class="timeline-row ${r.critical?'time-critical':''} ${pos.current===i?'is-current':pos.next===i?'is-next':''}" ${pos.current===i?'aria-current="step"':''}><div class="timeline-time">${inline(r.time)}</div><div class="timeline-text"><div class="timeline-heading"><strong class="step-title">${esc(r.stepTitle||'计划安排')}</strong><span class="step-state">${pos.current===i?'当前计划':pos.next===i?'下一项':''}</span>${r.critical?'<span class="step-key">关键时间</span>':''}</div>${timelineText(r)}${r.critical?`<p class="critical-note">${esc(r.critical)}</p>`:''}${relevant?`<button class="small-link" data-booking="${relevant.day}">查看关联预订 →</button>`:''}</div></article>`;}).join('')}</div>`;}
function extraDay(d){const k=representative(d),src=pImage(k);return `${src?`<section class="day-photography"><button class="summary-image" data-photo="${k}" aria-label="全屏查看${esc(DATA.places[k]?.name)}"><img src="${src}" ${photoAttributes(src)} width="1200" height="800" alt="${esc(DATA.places[k]?.name)}" loading="lazy"><span>查看照片 ⤢</span></button><p class="sun-summary">日出约 ${esc(d.sun[0])} · 日落约 ${esc(d.sun[1])}</p></section>`:''}${daySupplement()}<div class="expand-group"><button data-expand="notes" aria-expanded="false" aria-controls="notesPanel">补充资料 · 当日完整说明 <span>⌄</span></button><div id="notesPanel" class="expand-panel" inert><div><div class="rich">${markdown(d.notes||'')}</div></div></div></div>`;}
function dayView(isToday=false){const t=tripToday(new Date(),DATA.days,tripCalendarChanges),d=DATA.days[state.day-1];let boundary='';if(isToday&&!t.inTrip){const days=Math.max(0,Math.ceil((Date.parse(DATA.days[0].date+'T00:00:00+08:00')-Date.now())/86400000));boundary=t.boundary==='first'?`<aside class="journey-boundary"><p class="editor-label">旅行尚未开始</p><h2>距出发 ${days} 天</h2><p>下面是10月18日首日预览。</p><button data-view="itinerary">查看完整行程 →</button></aside>`:`<aside class="journey-boundary"><h2>旅程已结束</h2><p>下面是末日安排回顾。</p><button data-view="itinerary">回顾18天旅程 →</button></aside>`;}
return `${boundary}<header class="utility-header day-utility"><p class="editor-label">${dateText(d.date)} · ${esc(d.region)} · 第${d.id}天</p><h1>${esc(d.title)}</h1><div class="day-clock"><span>${isToday&&t.inTrip?'计划所在地':'此日目的地'} · <time data-clock-zone="${isToday&&t.inTrip?t.zone:d.tz}"></time></span><small>实时当地钟表 · 计划不等于实时行程状态</small></div><div class="utility-actions">${dateControl(dateText(d.date))}<button data-mapday="${d.id}">单日地图 ↗</button><button data-scroll-id="planTimeline">完整时间线 ↓</button>${d.hotel?`<button data-scroll-id="todayStay">今晚住宿 ↓</button>`:''}</div></header>${d.alert?`<div class="callout"><span>${inline(d.alert)}</span></div>`:''}<div id="planNow">${timeCard(d)}</div><div id="quickInformation"><div id="todayStay">${hotelQuick(d)}</div>${DATA.bookings.filter(b=>b.day===d.id).map(bookingQuick).join('')}${d.flights?.length?section('当天航班','FLIGHTS',`<p class="info-caption">以下起降时间均为当地时间，跨日按原航班注明。</p><div class="flights">${d.flights.map(flight).join('')}</div>`):''}</div>${routeChoice(d)}<section class="section day-timeline"><div class="section-top"><h2>当天完整安排</h2><button class="small-link" data-now>当前计划 ↓</button></div><div id="planTimeline">${renderTimeline(d)}</div></section><div id="dayExtras">${extraDay(d)}</div>${dayPagination(d)}`;}
function toolboxView(){return `<header class="utility-header"><p class="editor-label">FIELD TOOLS</p><h1>工具箱</h1><p>预订、住宿与实用资料，按使用场景查找。</p><div class="utility-actions">${dateControl()}<button data-offline>准备离线路书 ↓</button></div></header><div class="tool-grid">${[['activities','活动预订','观鲸 · 快艇 · 蓝冰洞 · 浮潜','ticket'],['flights','航班','起降时间 · 机场 · 转机提醒','plane'],['hotels','全部住宿','酒店地址 · 入住说明 · 导航','bed'],['transport','交通与自驾','路线备选 · 停车 · 付款与还车','car'],['emergency','天气与安全','官方天气、道路和应急资源','phone'],['lists','清单与采购','出发清单 · 四晚厨房采购','bag'],['offline','离线与备忘','保存关键资料 · 离线状态','book']].map(([k,n,s,i])=>`<button class="tool-item" data-tool="${k}">${ico(i)}<span><strong>${n}</strong><small>${s}</small></span><span>↗</span></button>`).join('')}</div><p class="info-caption">网站不提供天气、道路或航班实时状态；相关链接会打开官方查询页面。私人订单凭证请保存在自己的设备中。</p>`;}
function toolBody(k){if(k==='activities')return DATA.bookings.map(bookingQuick).join('');if(k==='flights')return DATA.days.filter(d=>d.flights?.length).map(d=>`<h2>${dateText(d.date)}</h2><button class="small-link" data-day="${d.id}">打开当天安排 →</button><div class="flights">${d.flights.map(flight).join('')}</div>`).join('');if(k==='hotels')return Object.entries(DATA.hotels).map(([key,h])=>`<article class="tool-hotel"><p class="editor-label">${DATA.days.filter(d=>d.hotel===key).map(d=>shortDate(d.date)).join(' / ')}</p>${hotelButton(key)}<p>${esc(h.address)}</p>${ext(hotelLink(key),'酒店导航','primary-link')}</article>`).join('');if(k==='transport')return `<div class="tool-list"><button data-detail="heltransport">赫尔辛基往返交通 →</button><button data-detail="norway">挪威自驾、停车与罚单 →</button><button data-detail="iceland">冰岛自驾、停车与还车 →</button><button data-day="1">首日 A/B 方案 →</button><button data-day="10">温泉 A/B 方案 →</button></div>`;if(k==='lists')return '<div class="tool-list"><button data-detail="packing">出发清单 →</button><button data-detail="groceries">四晚厨房采购 →</button></div>';if(k==='emergency')return emergency();return offlineBody();}
photoCard=(k,i)=>{const p=DATA.places[k],src=smallPhoto(k);return !p||!src?'':`<figure class="postcard"><button class="postcard-photo" data-photo="${k}" aria-label="全屏查看${esc(p.name)}"><img src="${src}" alt="${esc(p.name)}" loading="lazy" decoding="async" width="720" height="480"></button><figcaption class="postcard-footer"><button data-place="${k}">${esc(p.name)} <span>详情 ↗</span></button></figcaption></figure>`;};
